DROP TABLE IF EXISTS `alerts`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `alerts` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `category` enum('health','environment','radiation','device','wellness') NOT NULL,
  `severity` enum('normal','warning','critical') NOT NULL,
  `astronaut_id` bigint(20) unsigned DEFAULT NULL,
  `title` varchar(200) NOT NULL,
  `description` text NOT NULL,
  `possible_causes` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`possible_causes`)),
  `recommendation` text DEFAULT NULL,
  `confidence` decimal(3,2) NOT NULL,
  `basis_text` varchar(255) DEFAULT NULL,
  `confirmed_sensor_count` int(11) DEFAULT NULL,
  `related_metrics` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`related_metrics`)),
  `created_at` datetime(3) NOT NULL DEFAULT current_timestamp(3),
  `resolved_at` datetime(3) DEFAULT NULL,
  `acknowledged_by` bigint(20) unsigned DEFAULT NULL,
  `acknowledged_at` datetime(3) DEFAULT NULL,
  `escalated_at` datetime(3) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_alerts_astro_created` (`astronaut_id`,`created_at`),
  KEY `idx_alerts_category_severity` (`category`,`severity`),
  KEY `idx_alerts_resolved` (`resolved_at`),
  KEY `fk_alerts_acknowledger` (`acknowledged_by`),
  CONSTRAINT `fk_alerts_acknowledger` FOREIGN KEY (`acknowledged_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_alerts_astronaut` FOREIGN KEY (`astronaut_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

LOCK TABLES `alerts` WRITE;
/*!40000 ALTER TABLE `alerts` DISABLE KEYS */;
INSERT INTO `alerts` VALUES (1,'health','warning',3,'SpO2 trending below the safe range','SpO2 fell from 96% to 91% over the last 30 minutes and is now below the 95% safe floor. The trusted trend is corroborated by a heart rate of 103 bpm and respiration of 22/min.','[\"Pulse-oximeter placement issue\",\"Reduced oxygen saturation\",\"Motion artifact on the sensor\"]','Repeat the measurement at rest on the opposite hand. If SpO2 stays below 93%, start supplemental oxygen and notify the medical officer.',0.84,'Confirmed by 3 sensors',3,'[\"spo2\",\"heart_rate\",\"resp_rate\"]','2026-11-14 04:15:00.000',NULL,3,'2026-11-14 05:04:04.467','2026-11-14 05:04:06.649'),(2,'device','warning',3,'Pulse oximeter signal unstable','The pulse oximeter produced 2 low-confidence SpO2 samples in the last hour (84.0%–88.5%), which the trust layer removed from the clinical trend. The latest trusted SpO2 is 91%.','[\"Sensor placement\",\"Motion artifact\",\"Low perfusion\"]','Reposition the sensor on the opposite hand and take a resting reading.',0.62,'Unconfirmed: single sensor',1,'[\"spo2\"]','2026-11-14 03:50:24.197',NULL,2,'2026-11-14 04:51:24.218',NULL),(3,'radiation','warning',5,'Dose rate above 7-day average','The trusted dose rate is 94.2 µSv/h, 67% above the 7-day average rate of 56.5 µSv/h (1.357 mSv/day). The elevation has persisted for 6 hours.','[\"Solar particle event\",\"Dosimeter drift\"]','Confirm with the backup dosimeter and consider moving the sleep shift to the shielded module.',0.78,'Confirmed by 2 dosimeters',2,'[\"radiation\"]','2026-11-13 22:45:00.000',NULL,NULL,NULL,NULL),(4,'health','warning',6,'Transient temperature elevation','Body temperature reached 38.4 °C for 10 minutes and returned to 36.4 °C after rest. The latest trusted reading is back inside the safe range.','[\"Hot module\",\"Post-exercise\",\"Sensor contact\"]','Resolved after a repeat measurement; no further action.',0.52,'Unconfirmed: single sensor',1,'[\"body_temp\"]','2026-11-14 00:50:24.197','2026-11-14 01:15:24.197',NULL,NULL,NULL),(5,'environment','warning',NULL,'CO2 excursion in Node 2','Cabin CO2 rose to 1229 ppm and stayed above 1000 ppm for 120 minutes. The latest trusted reading is 868 ppm, back inside the safe range.','[\"Reduced airlock exchange\",\"Scrubber efficiency below nominal\",\"Crew activity in the module\"]','Resolved. Continue routine scrubber checks and confirm with the handheld CO2 meter.',0.79,'Confirmed by 3 sensors',3,'[\"co2\"]','2026-11-13 20:15:00.000','2026-11-13 22:25:00.000',NULL,NULL,NULL),(6,'environment','warning',NULL,'Air-quality spike in the Laboratory module','The air-quality index reached 101 AQI for 40 minutes and has returned to 22 AQI. The excursion was reported by a single node.','[\"Filter saturation\",\"Experiment off-gassing\",\"Sensor fault\"]','Resolved. Ventilate the module and verify the node with the next sample.',0.66,'Unconfirmed: single sensor',1,'[\"air_quality\"]','2026-11-13 23:55:00.000','2026-11-14 00:45:00.000',NULL,NULL,NULL);
/*!40000 ALTER TABLE `alerts` ENABLE KEYS */;
