INSERT INTO `medical_notes` VALUES (1,3,2,'instruction','Keep your right wrist still for 10 minutes after your next SpO2 reading so the sensor can settle. Reply with a check-in afterwards.','2026-11-14 01:45:08',NULL),(2,3,2,'note','SpO2 dip coincided with motion artifact. Trend is stable on the backup sensor; review again tomorrow.','2026-11-13 22:45:08','2026-11-13 23:45:08'),(3,3,2,'instruction','Log a seated check-in after EVA recovery and mention any dizziness.','2026-11-12 04:45:08','2026-11-12 05:15:08'),(4,4,2,'instruction','Re-seat the respiratory band before sleep and confirm the battery level.','2026-11-14 00:45:08',NULL),(5,4,2,'note','Sleep debt is accumulating. Reduced exercise intensity until fatigue returns to 2/5.','2026-11-13 08:45:08','2026-11-13 09:45:08'),(6,6,2,'note','Heart-rate elevation at rest discussed. Likely pre-EVA stress; repeat reading after hydration.','2026-11-14 03:25:08',NULL),(7,7,2,'instruction','Move tonight’s sleep block 30 minutes earlier and log the result in the morning check-in.','2026-11-14 02:55:08','2026-11-14 03:05:08'),(8,8,2,'note','Blood-pressure cuff conflict confirmed as a cuff placement issue. Use the arterial line for the next 24 hours.','2026-11-14 02:35:08',NULL);
